				font-style: normal;\r\n			}\r\n			@font-face {\r\n				font-family: WooCommerce;\r\n				src: url(http://wordpress.local/CK_NHOMF_CMS/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.eot);\r\n				src:\r\n					url(http://wordpress.local/CK_NHOMF_CMS/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.eot?#iefix) format(\"embedded-opentype\"),\r\n					url(http://wordpress.local/CK_NHOMF_CMS/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.woff) format(\"woff\"),\r\n					url(http://wordpress.local/CK_NHOMF_CMS/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.ttf) format(\"truetype\"),\r\n					url(http://wordpress.local/CK_NHOMF_CMS/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.svg#WooCommerce) format(\"svg\");\r\n				font-weight: 400;\r\n				font-style: normal;\r\n			}\n\r\n			a.cart-contents,\r\n			.site-header-cart .widget_shopping_cart a {\r\n				color: #333333;\r\n			}\r\n\r\n			a.cart-contents:hover,\r\n			.site-header-cart .widget_shopping_cart a:hover,\r\n			.site-header-cart:hover > li > a {\r\n				color: #747474;\r\n			}\r\n\r\n			table.cart td.product-remove,\r\n			table.cart td.actions {\r\n				border-top-color: #ffffff;\r\n			}\r\n\r\n			.storefront-handheld-footer-bar ul li.cart .count {\r\n				background-color: #333333;\r\n				color: #ffffff;\r\n				border-color: #ffffff;\r\n			}\r\n\r\n			.woocommerce-tabs ul.tabs li.active a,\r\n			ul.products li.product .price,\r\n			.onsale,\r\n			.wc-block-grid__product-onsale,\r\n			.widget_search form:before,\r\n			.widget_product_search form:before {\r\n				color: #6d6d6d;\r\n			}\r\n\r\n			.woocommerce-breadcrumb a,\r\n			a.woocommerce-review-link,\r\n			.product_meta a {\r\n				color: #727272;\r\n			}\r\n\r\n			.wc-block-grid__product-onsale,\r\n			.onsale {\r\n				border-color: #6d6d6d;\r\n			}\r\n\r\n			.star-rating span:before,\r\n			.quantity .plus, .quantity .minus,\r\n			p.stars a:hover:after,\r\n			p.stars a:after,\r\n			.star-rating span:before,\r\n			#payment .payment_methods li input[type=radio]:first-child:checked+label:before {\r\n				color: #7f54b3;\r\n			}\r\n\r\n			.widget_price_filter .ui-slider .ui-slider-range,\r\n			.widget_price_filter .ui-slider .ui-slider-handle {\r\n				background-color: #7f54b3;\r\n			}\r\n\r\n			.order_details {\r\n				background-color: #f8f8f8;\r\n			}\r\n\r\n			.order_details > li {\r\n				border-bottom: 1px dotted #e3e3e3;\r\n			}\r\n\r\n			.order_details:before,\r\n			.order_details:after {\r\n				background: -webkit-linear-gradient(transparent 0,transparent 0),-webkit-linear-gradient(135deg,#f8f8f8 33.33%,transparent 33.33%),-webkit-linear-gradient(45deg,#f8f8f8 33.33%,transparent 33.33%)\r\n			}\r\n\r\n			#order_review {\r\n				background-color: #ffffff;\r\n			}\r\n\r\n			#payment .payment_methods > li .payment_box,\r\n			#payment .place-order {\r\n				background-color: #fafafa;\r\n			}\r\n\r\n			#payment .payment_methods > li:not(.woocommerce-notice) {\r\n				background-color: #f5f5f5;\r\n			}\r\n\r\n			#payment .payment_methods > li:not(.woocommerce-notice):hover {\r\n				background-color: #f0f0f0;\r\n			}\r\n\r\n			.woocommerce-pagination .page-numbers li .page-numbers.current {\r\n				background-color: #e6e6e6;\r\n				color: #636363;\r\n			}\r\n\r\n			.wc-block-grid__product-onsale,\r\n			.onsale,\r\n			.woocommerce-pagination .page-numbers li .page-numbers:not(.current) {\r\n				color: #6d6d6d;\r\n			}\r\n\r\n			p.stars a:before,\r\n			p.stars a:hover~a:before,\r\n			p.stars.selected a.active~a:before {\r\n				color: #6d6d6d;\r\n			}\r\n\r\n			p.stars.selected a.active:before,\r\n			p.stars:hover a:before,\r\n			p.stars.selected a:not(.active):before,\r\n			p.stars.selected a.active:before {\r\n				color: #7f54b3;\r\n			}\r\n\r\n			.single-product div.product .woocommerce-product-gallery .woocommerce-product-gallery__trigger {\r\n				background-color: #eeeeee;\r\n				color: #333333;\r\n			}\r\n\r\n			.single-product div.product .woocommerce-product-gallery .woocommerce-product-gallery