(198, 0, '2026-10-23 13:04:00', '2026-10-23 06:04:00', '<!-- wp:paragraph {\"className\":\"nem-new-container nem-new-breadcrumb\"} -->\n<p class=\"nem-new-container nem-new-breadcrumb\"><a href=\"http://wordpress.local/CK_NHOMF_CMS/\">TRANG CHỦ</a> / SẢN PHẨM MỚI</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":234,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"nem-new-banner\"} -->\n<figure class=\"wp-block-image size-full nem-new-banner\"><img src=\"http://wordpress.local/CK_NHOMF_CMS/wp-content/uploads/nem-new-products/banner.webp\" alt=\"Nhẹ bước mỗi ngày - Casual Collection NEM\" class=\"wp-image-234\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:columns {\"isStackedOnMobile\":false,\"className\":\"nem-new-container nem-new-layout\"} -->\n<div class=\"wp-block-columns is-not-stacked-on-mobile nem-new-container nem-new-layout\"><!-- wp:column {\"width\":\"260px\",\"className\":\"nem-new-sidebar\"} -->\n<div class=\"wp-block-column nem-new-sidebar\" style=\"flex-basis:260px\"><!-- wp:group {\"className\":\"nem-categories-box\"} -->\n<div class=\"wp-block-group nem-categories-box\"><!-- wp:heading {\"level\":3,\"className\":\"nem-new-categories-title\"} -->\n<h3 class=\"wp-block-heading nem-new-categories-title\">Danh mục</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nem-new-category-all nem-cat-slug-all is-active\"} -->\n<p class=\"nem-new-category-all nem-cat-slug-all is-active\">Tất cả sản phẩm</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"nem-new-category-group\"} -->\n<div class=\"wp-block-group nem-new-category-group\"><!-- wp:paragraph {\"className\":\"nem-new-category-parent nem-cat-slug-dam\"} -->\n<p class=\"nem-new-category-parent nem-cat-slug-dam\">Đầm</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"nem-new-category-child nem-cat-slug-dam-suong\"} -->\n<p class=\"nem-new-category-child nem-cat-slug-dam-suong\">Đầm suông</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"classNa